\title{A Unified Theory of Positional Number Systems: \\
The Factorial System as a Mixed-Radix Instance}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We develop the theory of \emph{mixed-radix positional number systems} --
positional representations in which each column may carry its own base -- and
prove, in full generality and from first principles, that valid representations
of a fixed length are unique and that they exist for every number below the
running product of the bases. We then establish a precise \emph{bridge}: the
classical \emph{factorial number system} (factoradic) is exactly the mixed-radix
system whose base at column $i$ is $i+1$. Three bridge theorems show that the
place values agree ($\prod_{j<i}(j+1) = i!$), that the validity conditions agree
($c_i < i+1 \iff c_i \le i$), and that uniqueness for the factorial system is a
strict corollary of the general mixed-radix uniqueness theorem. The development
is non-circular: uniqueness is proved directly from a digit-bound estimate and
two Euclidean splitting identities, without cardinality, surjectivity, or any
bijection theorem. Ordinary base-$N$ numerals arise as the companion instance
$b_i = N$, exhibiting decimal, binary, and factoradic representations as three
points of one parameterized family.
\end{abstract}

\maketitle

\section{Introduction}

The decimal expansion $2025 = 2\cdot 10^3 + 0\cdot 10^2 + 2\cdot 10 + 5$ is the
prototype of a \emph{positional} number system: a sequence of place values (here
the powers of ten) with digits below a fixed base. The constancy of the base is
inessential. Allowing the base to vary from column to column yields the
\emph{mixed-radix} systems, among which the \emph{factorial number system} --
with place values $1,1,2,6,24,120,\dots$ -- is a particularly clean instance.

This paper gives a self-contained account of mixed-radix systems, culminating in
the two theorems that make any positional system usable, \textbf{uniqueness} and
\textbf{existence}, and then proves that the factorial number system is literally
the mixed-radix instance $b_i = i+1$, so that every structural result transports
for free. The technical heart is that uniqueness never uses the \emph{specific}
running product; it uses only that the running product is positive, which a single
valid digit already guarantees.

\section{Definitions}

Throughout, $\mathbb{N} = \{0,1,2,\dots\}$. A \emph{base sequence} is a function
$b : \mathbb{N} \to \mathbb{N}$, and a \emph{digit function} is a function
$c : \mathbb{N} \to \mathbb{N}$.

\begin{definition}[Running product / place value]
For a base sequence $b$ and $k \in \mathbb{N}$, the \emph{running product} is
$P_b(k) = \prod_{i<k} b_i$, with $P_b(0) = 1$. It satisfies
$P_b(k+1) = P_b(k)\,b_k$.
\end{definition}

\begin{definition}[Mixed-radix value]
The \emph{length-$k$ value} of $c$ under $b$ is
$V_b(c,k) = \sum_{i<k} c_i\, P_b(i)$, with $V_b(c,0)=0$ and
$V_b(c,k+1) = V_b(c,k) + c_k\, P_b(k)$.
\end{definition}

\begin{definition}[Validity]
A digit function $c$ is \emph{valid up to length $k$}, written $\Valid_b(c,k)$, if
$c_i < b_i$ for all $i<k$. Validity is monotone: $\Valid_b(c,k+1)$ implies
$\Valid_b(c,k)$.
\end{definition}

\begin{definition}[Factoradic value and validity]
The \emph{factoradic value} is $F(c,k) = \sum_{i<k} c_i\, i!$, and $c$ is
\emph{factoradic-valid} up to $k$, written $\ValidF(c,k)$, if $c_i \le i$ for all
$i<k$.
\end{definition}

\section{The Digit-Bound Estimate}

\begin{lemma}[Positivity from validity]\label{lem:pos}
If $\Valid_b(c,k+1)$, then $P_b(k) > 0$.
\end{lemma}
\begin{proof}
For $i<k$, validity gives $c_i < b_i$, so $b_i \ge 1$. A product of positive
naturals is positive, hence $P_b(k) = \prod_{i<k} b_i > 0$.
\end{proof}

\begin{theorem}[Digit-bound estimate]\label{thm:bound}
If $\Valid_b(c,k)$, then $V_b(c,k) < P_b(k)$.
\end{theorem}
\begin{proof}
Induction on $k$. For $k=0$, $0 < 1$. Assume the claim for $k$ and suppose
$\Valid_b(c,k+1)$. By monotonicity and the inductive hypothesis, $V_b(c,k) \le
P_b(k)-1$, and validity at $k$ gives $c_k \le b_k - 1$. Then
\[
V_b(c,k+1) = V_b(c,k) + c_k P_b(k) \le (P_b(k)-1) + (b_k-1)P_b(k)
= P_b(k+1) - 1 < P_b(k+1). \qedhere
\]
\end{proof}

\section{The Euclidean Splitting Identities}

\begin{theorem}[Splitting by division]\label{thm:div}
If $\Valid_b(c,k+1)$, then $\lfloor V_b(c,k+1)/P_b(k)\rfloor = c_k$.
\end{theorem}
\begin{proof}
Write $V_b(c,k+1) = V_b(c,k) + c_k P_b(k)$. By Theorem~\ref{thm:bound},
$V_b(c,k) < P_b(k)$, and by Lemma~\ref{lem:pos}, $P_b(k)>0$; hence
$\lfloor V_b(c,k)/P_b(k)\rfloor = 0$ and the quotient is $c_k$.
\end{proof}

\begin{theorem}[Splitting by remainder]\label{thm:mod}
If $\Valid_b(c,k+1)$, then $V_b(c,k+1) \bmod P_b(k) = V_b(c,k)$.
\end{theorem}
\begin{proof}
The term $c_k P_b(k)$ is divisible by $P_b(k)$, so the residue is
$V_b(c,k)\bmod P_b(k) = V_b(c,k)$ by Theorem~\ref{thm:bound}.
\end{proof}

\section{Uniqueness}

\begin{theorem}[Uniqueness]\label{thm:unique}
If $\Valid_b(c,k)$, $\Valid_b(d,k)$, and $V_b(c,k) = V_b(d,k)$, then $c_i = d_i$
for all $i<k$.
\end{theorem}
\begin{proof}
Induction on $k$; the base case is vacuous. For the step, by
Theorem~\ref{thm:div} applied to both strings and equality of values,
$c_k = \lfloor V_b(c,k+1)/P_b(k)\rfloor = \lfloor V_b(d,k+1)/P_b(k)\rfloor = d_k$.
By Theorem~\ref{thm:mod}, $V_b(c,k) = V_b(d,k)$, so the inductive hypothesis gives
$c_i = d_i$ for $i<k$; with $c_k = d_k$ this covers $i<k+1$.
\end{proof}

The proof uses only validity, Theorems~\ref{thm:bound}--\ref{thm:mod}, and
induction; it does not invoke cardinality, surjectivity, or any bijection
theorem, so existence may safely be proved afterward.

\section{Existence}

\begin{definition}[Digit extraction]
For $n\in\mathbb{N}$, set $\mathrm{digit}_b(n)(i) = \lfloor n/P_b(i)\rfloor \bmod
b_i$.
\end{definition}

\begin{lemma}
If $b_i > 0$ for all $i$, then $\Valid_b(\mathrm{digit}_b(n),k)$ for all $n,k$.
\end{lemma}
\begin{proof}
$\mathrm{digit}_b(n)(i) = (\cdot)\bmod b_i < b_i$ when $b_i > 0$.
\end{proof}

\begin{theorem}[Existence / surjectivity]\label{thm:exist}
If $n < P_b(k)$, then $V_b(\mathrm{digit}_b(n),k) = n$.
\end{theorem}
\begin{proof}
Induction on $m$ establishes
\[
n = \sum_{i<m} \big(\lfloor n/P_b(i)\rfloor \bmod b_i\big)P_b(i)
      + \lfloor n/P_b(m)\rfloor P_b(m),
\]
using $\lfloor n/P_b(m+1)\rfloor = \lfloor \lfloor n/P_b(m)\rfloor/b_m\rfloor$ and
the division algorithm at each step. At $m=k$, $n<P_b(k)$ forces
$\lfloor n/P_b(k)\rfloor = 0$, collapsing the trailing term.
\end{proof}

\begin{corollary}[Bijection]
For every $k$, $c \mapsto V_b(c,k)$ is a bijection between valid length-$k$ digit
strings and $\{0,\dots,P_b(k)-1\}$.
\end{corollary}

\section{The Factorial Bridge}

\begin{lemma}[Running product is the factorial]\label{lem:fact}
For $b_i = i+1$, $P_b(k) = \prod_{j<k}(j+1) = k!$.
\end{lemma}
\begin{proof}
Induction: $P_b(0)=1=0!$ and $P_b(k+1)=P_b(k)(k+1)=k!(k+1)=(k+1)!$.
\end{proof}

\begin{theorem}[Place values agree]\label{thm:val}
For all $c,k$, $V_{(i+1)}(c,k) = F(c,k) = \sum_{i<k} c_i\, i!$.
\end{theorem}
\begin{proof}
Term by term, $c_i P_b(i) = c_i\, i!$ by Lemma~\ref{lem:fact}.
\end{proof}

\begin{theorem}[Validity conditions agree]\label{thm:valid}
For all $c,k$, $\Valid_{(i+1)}(c,k) \iff \ValidF(c,k)$.
\end{theorem}
\begin{proof}
At each $i<k$ the conditions $c_i < i+1$ and $c_i \le i$ are equivalent over
$\mathbb{N}$.
\end{proof}

\begin{theorem}[Factoradic uniqueness, re-derived]\label{thm:factunique}
If $\ValidF(c,k)$, $\ValidF(d,k)$, and $F(c,k)=F(d,k)$, then $c_i = d_i$ for all
$i<k$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:valid} both strings are $\Valid_{(i+1)}$, and by
Theorem~\ref{thm:val} their mixed-radix values equal their factoradic values, so
$V_{(i+1)}(c,k) = V_{(i+1)}(d,k)$. Apply Theorem~\ref{thm:unique} with $b_i=i+1$.
\end{proof}

Thus factoradic uniqueness is a strict instance of the general theorem;
factoradic existence is the specialization of Theorem~\ref{thm:exist}.

\section{Base-$N$ and Boundary Cases}

\begin{proposition}
For $b_i = N$, $P_b(k) = N^k$ and validity is ``each digit lies in
$\{0,\dots,N-1\}$''. Base-$N$ uniqueness and existence are instances of
Theorems~\ref{thm:unique} and~\ref{thm:exist}.
\end{proposition}

At $k=0$ every value collapses to $0$ and validity holds vacuously: the empty
string represents $0$ in all systems at once. If some $b_i = 0$, no digit
satisfies $c_i < 0$, so validity is unsatisfiable beyond column $i$ and all
statements over valid representations hold vacuously.

\section{Applications}

\textbf{Permutation ranking (Lehmer code).} Since valid length-$k$ factoradic
strings biject with $\{0,\dots,k!-1\}$ and $k!$ counts permutations of $k$
symbols, the factoradic gives an arithmetic bijection between integers and
permutations. The digit $c_i$ records how many unused symbols are skipped at step
$i$; counting up in factoradic enumerates permutations lexicographically, yielding
$O(k\log k)$ ranking and unranking without materializing intermediate
permutations.

\textbf{Variable-radix encodings.} Any positive base sequence yields a faithful
positional encoding of an interval -- combinatorial number systems, clock and
calendar arithmetic (bases $60,60,24,\dots$), and product-space indexing.

\section{Discussion and Future Directions}

Place value, not any particular base, guarantees unique representation: the
digit-bound estimate (odometer rollover at the running product) plus Euclidean
splitting is the whole engine. Directions:
(1) uniqueness for every eventually-positive base sequence;
(2) carry-free positional arithmetic with per-position work depending only on
local bases;
(3) factoradic digit sums equal to permutation inversion counts under the Lehmer
bijection;
(4) growth of Fibonacci primitive parts, driven by cyclotomic-type magnitude
$\sim \varphi^{\phi(n)}$.

\section{Conclusion}

We have given a self-contained, non-circular development of mixed-radix positional
number systems and shown that the factorial system is precisely the instance
$b_i = i+1$. The three bridge theorems demonstrate that the classical factoradic
results are corollaries of the general theory, with base-$N$ numerals as a
parallel instance.

\end{document}

