"""Uniqueness and existence: valid factoradic strings biject with {0,...,k!-1}."""
from __future__ import annotations
from math import factorial
from typing import Callable, List

def running_product(b: Callable[[int], int], k: int) -> int:
    p = 1
    for i in range(k):
        p *= b(i)
    return p

def value(b: Callable[[int], int], c: List[int], k: int) -> int:
    return sum(c[i] * running_product(b, i) for i in range(k))

def extract_digits(b: Callable[[int], int], n: int, k: int) -> List[int]:
    return [(n // running_product(b, i)) % b(i) for i in range(k)]

def main(k: int = 5) -> None:
    b = lambda i: i + 1
    seen = {}
    for n in range(factorial(k)):
        d = extract_digits(b, n, k)
        assert all(0 <= d[i] <= i for i in range(k))   # validity  c[i] <= i
        assert value(b, d, k) == n                     # existence: reconstructs n
        assert tuple(d) not in seen                    # uniqueness: no collisions
        seen[tuple(d)] = n
    print(f"All {factorial(k)} integers 0..{factorial(k)-1} have a unique valid length-{k} string.")

if __name__ == "__main__":
    main()

