from typing import Callable, List

def running_product(b: Callable[[int], int], k: int) -> int:
    p = 1
    for i in range(k):
        p *= b(i)
    return p

def value(b: Callable[[int], int], c: List[int], k: int) -> int:
    return sum(c[i] * running_product(b, i) for i in range(k))

def digits_from_value(b: Callable[[int], int], v: int, k: int) -> List[int]:
    """Recover digits by repeated Euclidean splitting: top = v // P_b(k-1), then recurse.

    Correct by the splitting identities; the result is unique by the uniqueness theorem.
    """
    digits = [0] * k
    for i in range(k - 1, -1, -1):
        P = running_product(b, i)
        digits[i] = v // P
        v = v % P
    return digits
